// Find all parameter headers (h3 elements with class containing 'parameter') 
// and their descriptions within the Trainer class documentation
var sections = document.querySelectorAll('section[id^="transformers.Trainer"], section[id^="transformers.TrainingArguments"]');
var results = [];
sections.forEach(function(sec) {
  var h = sec.querySelector('h2, h3');
  var title = h ? h.textContent.trim() : sec.id;
  results.push({id: sec.id, title: title});
});
return results;

// Find all section headings within the main documentation content
var main = document.querySelector('main, article, .prose, [role="main"]') || document.body;
var headings = main.querySelectorAll('h1, h2, h3, h4, h5');
var results = [];
headings.forEach(function(h) {
  results.push({tag: h.tagName, text: h.textContent.trim().substring(0, 100), id: h.id});
});
return results.slice(0, 60);

// Find the constructor/initialization of Trainer class
var main = document.querySelector('main, article, .prose, [role="main"]') || document.body;
// Look for the init signature/code block
var codeBlocks = main.querySelectorAll('pre, code');
var results = [];
codeBlocks.forEach(function(cb) {
  var text = cb.textContent;
  if (text.includes('def __init__') || text.includes('class transformers.Trainer')) {
    results.push({tag: cb.tagName, text: text.substring(0, 1500)});
  }
});
return results.slice(0, 10);

// Find the class init signature, look at all code blocks
var main = document.querySelector('main, article, .prose, [role="main"]') || document.body;
var codeBlocks = main.querySelectorAll('pre, code');
var results = [];
codeBlocks.forEach(function(cb, i) {
  var text = cb.textContent.trim();
  // First 100 characters
  if (text.length > 50 && (text.includes('Trainer') || text.includes('TrainingArguments') || text.includes('def ') || text.includes('class '))) {
    results.push({index: i, tag: cb.tagName, preview: text.substring(0, 200)});
  }
});
return results.slice(0, 20);

// Look for the actual Trainer class definition with init parameters
var main = document.querySelector('main, article, .prose, [role="main"]') || document.body;
var codeBlocks = main.querySelectorAll('pre');
var results = [];
codeBlocks.forEach(function(cb, i) {
  var text = cb.textContent.trim();
  // Get code blocks that look like signatures (multi-line with Trainer or TrainingArguments)
  if (text.length > 100 && text.length < 5000) {
    if (text.includes('model:') && (text.includes('args:') || text.includes('Trainer'))) {
      results.push({index: i, length: text.length, preview: text.substring(0, 1000)});
    }
  }
});
return results.slice(0, 10);

// Find all pre/code blocks and search for the Trainer constructor signature
var allCode = document.querySelectorAll('pre');
var results = [];
for (var i = 0; i < allCode.length; i++) {
  var text = allCode[i].textContent;
  // Look for class Trainer definitions with init signature
  if (text.includes('class transformers.Trainer') || text.match(/Trainer\s*\(\s*\n\s*model/)) {
    results.push({index: i, text: text.substring(0, 3000)});
  }
  if (text.includes('__init__') && text.length < 5000) {
    results.push({index: i, text: text.substring(0, 3000)});
  }
}
return results.slice(0, 5);

// Look for parameter definitions in the page
// HuggingFace uses specific HTML structure - let's look at all elements
var main = document.querySelector('article') || document.body;
// Find all definitions within the article that look like parameter defs
var defs = main.querySelectorAll('dl, .parameter, [class*="parameter"]');
var results = [];
defs.forEach(function(d, i) {
  var text = d.textContent.trim();
  if (text.length > 30) {
    results.push({tag: d.tagName, class: d.className.substring(0, 100), preview: text.substring(0, 300)});
  }
});
return results.slice(0, 30);
